import React, { useEffect, useRef, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import createDuelSocket from "../utils/duelSocket";

const headerStyles = {
  wrapper: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    padding: "12px 20px",
    background:
      "linear-gradient(135deg, rgba(15,23,42,0.95) 0%, rgba(30,64,175,0.95) 100%)",
    color: "#e5e7eb",
    borderBottom: "1px solid rgba(148,163,184,0.3)",
  },
  logo: {
    fontWeight: 800,
    fontSize: 20,
    letterSpacing: "0.08em",
  },
  right: {
    display: "flex",
    alignItems: "center",
    gap: 10,
  },
  button: {
    borderRadius: 999,
    padding: "6px 14px",
    fontSize: 13,
    fontWeight: 500,
    border: "1px solid transparent",
    cursor: "pointer",
    display: "inline-flex",
    alignItems: "center",
    gap: 6,
  },
  copyButton: {
    background: "rgba(15,23,42,0.9)",
    color: "#e5e7eb",
    borderColor: "rgba(148,163,184,0.5)",
  },
  leaveButton: {
    background:
      "linear-gradient(135deg, rgba(248,113,113,1) 0%, rgba(239,68,68,1) 100%)",
    color: "#0b1020",
    borderColor: "rgba(248,113,113,0.8)",
  },
};

export default function EditorPage() {
  const { roomId } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();

  const [socket, setSocket] = useState(null);
  const [clients, setClients] = useState([]);
  const [code, setCode] = useState(
    `// Collaborative editor\n// Everyone in this room sees the same code in real time.\n\nfunction hello() {\n  console.log("Hello from ${roomId}!");\n}\n`
  );
  const [copyLabel, setCopyLabel] = useState("Copy room ID");

  const [chatMessages, setChatMessages] = useState([]);
  const [chatInput, setChatInput] = useState("");

  const codeRef = useRef(code);
  const chatEndRef = useRef(null);

  useEffect(() => {
    if (!roomId) return;

    const s = createDuelSocket();
    setSocket(s);

    const username = user?.username || user?.email || "Guest";

    s.on("connect", () => {
      s.emit("collab_join", { roomId, username });
    });

    s.on("collab_clients", ({ clients: list = [] } = {}) => {
      setClients(list);
    });

    s.on("collab_sync_code", ({ code: initialCode = "" } = {}) => {
      codeRef.current = initialCode || "";
      setCode(initialCode || "");
    });

    s.on("collab_code_change", ({ code: newCode = "" } = {}) => {
      codeRef.current = newCode;
      setCode(newCode);
    });

    s.on("collab_chat_message", (msg) => {
      setChatMessages((prev) => [...prev, msg]);
    });

    return () => {
      s.off("collab_clients");
      s.off("collab_sync_code");
      s.off("collab_code_change");
      s.off("collab_chat_message");
      s.disconnect();
    };
  }, [roomId, user]);

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [chatMessages]);

  const handleCopyRoomId = async () => {
    if (!roomId) return;
    try {
      await navigator.clipboard.writeText(roomId);
      setCopyLabel("Copied!");
      setTimeout(() => setCopyLabel("Copy room ID"), 1500);
    } catch {
      setCopyLabel("Failed");
      setTimeout(() => setCopyLabel("Copy room ID"), 1500);
    }
  };

  const handleLeave = () => {
    if (socket) {
      socket.disconnect();
    }
    navigate("/simple-editor");
  };

  const handleCodeChange = (e) => {
    const newCode = e.target.value;
    setCode(newCode);
    codeRef.current = newCode;
    if (socket) {
      socket.emit("collab_code_change", { roomId, code: newCode });
    }
  };

  const sendChat = () => {
    if (!socket) return;
    const text = (chatInput || "").trim();
    if (!text) return;
    const username = user?.username || user?.email || "Guest";
    socket.emit(
      "collab_chat_message",
      { roomId, username, message: text },
      (res = {}) => {
        if (res.ok) {
          setChatInput("");
        }
      }
    );
  };

  const displayName = user?.username || user?.email || "Guest";

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "#020617",
        color: "#e5e7eb",
        display: "flex",
        flexDirection: "column",
      }}
    >
      <header style={headerStyles.wrapper}>
        <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
          <div style={headerStyles.logo}>CodeGen4Future</div>
          <div style={{ fontSize: 13, opacity: 0.75 }}>
            Room: <strong>{roomId}</strong> · You are{" "}
            <strong>{displayName}</strong>
          </div>
        </div>
        <div style={headerStyles.right}>
          <button
            type="button"
            style={{ ...headerStyles.button, ...headerStyles.copyButton }}
            onClick={handleCopyRoomId}
          >
            📋 {copyLabel}
          </button>
          <button
            type="button"
            style={{ ...headerStyles.button, ...headerStyles.leaveButton }}
            onClick={handleLeave}
          >
            🚪 Leave
          </button>
        </div>
      </header>

      <div
        style={{
          flex: 1,
          display: "grid",
          gridTemplateColumns: "minmax(0, 1.4fr) minmax(280px, 0.9fr)",
          gap: 16,
          padding: 16,
          boxSizing: "border-box",
        }}
      >
        {/* Code editor */}
        <section
          style={{
            background: "#020617",
            borderRadius: 14,
            border: "1px solid #1f2937",
            boxShadow: "0 0 0 1px rgba(15,23,42,0.7)",
            display: "flex",
            flexDirection: "column",
          }}
        >
          <div
            style={{
              padding: "10px 14px",
              borderBottom: "1px solid #1f2937",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <div style={{ fontSize: 14, fontWeight: 600 }}>
              Collaborative Code Editor
            </div>
            <div style={{ fontSize: 12, opacity: 0.7 }}>
              {clients.length}{" "}
              {clients.length === 1 ? "user online" : "users online"}
            </div>
          </div>
          <textarea
            value={code}
            onChange={handleCodeChange}
            spellCheck="false"
            style={{
              flex: 1,
              minHeight: 0,
              border: "none",
              outline: "none",
              resize: "none",
              background: "#020617",
              color: "#e5e7eb",
              fontFamily: "JetBrains Mono, Menlo, Monaco, Consolas, monospace",
              fontSize: 14,
              padding: 14,
              lineHeight: 1.5,
              whiteSpace: "pre",
            }}
            placeholder="// Start typing to collaborate..."
          />
        </section>

        {/* Sidebar: users + chat */}
        <section
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 12,
          }}
        >
          {/* Connected users */}
          <div
            style={{
              background: "#020617",
              borderRadius: 14,
              border: "1px solid #1f2937",
              boxShadow: "0 0 0 1px rgba(15,23,42,0.7)",
              padding: 12,
              display: "flex",
              flexDirection: "column",
              gap: 8,
            }}
          >
            <div
              style={{
                fontSize: 14,
                fontWeight: 600,
                marginBottom: 4,
                display: "flex",
                alignItems: "center",
                gap: 6,
              }}
            >
              <span>👥</span>
              <span>Connected Users</span>
            </div>
            {clients.length === 0 ? (
              <div style={{ fontSize: 13, opacity: 0.7 }}>
                Waiting for others to join this room…
              </div>
            ) : (
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  gap: 6,
                  maxHeight: 160,
                  overflowY: "auto",
                }}
              >
                {clients.map((c) => (
                  <div
                    key={c.socketId}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 8,
                      padding: "6px 8px",
                      borderRadius: 10,
                      background: "rgba(15,23,42,0.7)",
                      border: "1px solid rgba(55,65,81,0.8)",
                    }}
                  >
                    <div
                      style={{
                        width: 26,
                        height: 26,
                        borderRadius: "999px",
                        background:
                          "linear-gradient(135deg, #6366f1, #ec4899)",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        fontSize: 13,
                        fontWeight: 700,
                        color: "#0f172a",
                      }}
                    >
                      {c.username?.charAt(0)?.toUpperCase() || "U"}
                    </div>
                    <div
                      style={{
                        display: "flex",
                        flexDirection: "column",
                      }}
                    >
                      <span style={{ fontSize: 13, fontWeight: 500 }}>
                        {c.username || "User"}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Chat */}
          <div
            style={{
              flex: 1,
              minHeight: 0,
              background: "#020617",
              borderRadius: 14,
              border: "1px solid #1f2937",
              boxShadow: "0 0 0 1px rgba(15,23,42,0.7)",
              display: "flex",
              flexDirection: "column",
            }}
          >
            <div
              style={{
                padding: "10px 12px",
                borderBottom: "1px solid #1f2937",
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 6,
                  fontSize: 14,
                  fontWeight: 600,
                }}
              >
                <span>💬</span>
                <span>Room Chat</span>
              </div>
              <div style={{ fontSize: 11, opacity: 0.7 }}>
                {chatMessages.length} message
                {chatMessages.length === 1 ? "" : "s"}
              </div>
            </div>
            <div
              style={{
                flex: 1,
                minHeight: 0,
                padding: 10,
                overflowY: "auto",
                display: "flex",
                flexDirection: "column",
                gap: 8,
              }}
            >
              {chatMessages.length === 0 ? (
                <div
                  style={{
                    fontSize: 13,
                    opacity: 0.7,
                    fontStyle: "italic",
                    textAlign: "center",
                    marginTop: 16,
                  }}
                >
                  No messages yet. Say hi! 👋
                </div>
              ) : (
                chatMessages.map((m) => (
                  <div
                    key={m.id}
                    style={{
                      display: "flex",
                      flexDirection: "column",
                      gap: 2,
                      padding: "6px 8px",
                      borderRadius: 10,
                      background: "rgba(15,23,42,0.9)",
                      border: "1px solid rgba(55,65,81,0.8)",
                    }}
                  >
                    <div
                      style={{
                        fontSize: 12,
                        fontWeight: 600,
                        color: "#a5b4fc",
                      }}
                    >
                      {m.username || "User"}
                    </div>
                    <div style={{ fontSize: 13 }}>{m.message}</div>
                  </div>
                ))
              )}
              <div ref={chatEndRef} />
            </div>
            <div
              style={{
                padding: 10,
                borderTop: "1px solid #1f2937",
                display: "flex",
                gap: 8,
              }}
            >
              <input
                type="text"
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    sendChat();
                  }
                }}
                placeholder="Type a message…"
                style={{
                  flex: 1,
                  borderRadius: 999,
                  border: "1px solid rgba(75,85,99,0.9)",
                  padding: "8px 12px",
                  fontSize: 13,
                  background: "#020617",
                  color: "#e5e7eb",
                  outline: "none",
                }}
              />
              <button
                type="button"
                onClick={sendChat}
                disabled={!chatInput.trim()}
                style={{
                  borderRadius: 999,
                  padding: "8px 16px",
                  fontSize: 13,
                  fontWeight: 600,
                  border: "none",
                  cursor: chatInput.trim() ? "pointer" : "not-allowed",
                  background: chatInput.trim()
                    ? "linear-gradient(135deg,#6366f1,#ec4899)"
                    : "rgba(55,65,81,0.8)",
                  color: "#0f172a",
                }}
              >
                Send
              </button>
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}
